// Use unwind and sort in mongo // let arr = $.sort((a,b)=>a.steps>b.steps ? 1 : a.steps < b.steps ? -1 : a.from < b.from ? 1 : -1)

// this should probably use a for loop for performance reasons (lots of object re-creation/cloning w/ reduce)
return $.reduce((a,c,i)=>{
  const d = [...a.nodes]
  const w = [...a.width]
  const n = {...a.n}
  if(i===0){n["1"]={["10"]:`${c.from}`}}
  n[`${Math.floor(c.order/10)}`]={...n[`${Math.floor(c.order/10)}`], [`${c.order}`]:`${c.to}`}
 //d.length===c.steps+1 ? d.push({[c.from]:[c.to]}) : d[c.steps+1][c.from] ? d[c.steps+1][c.from] = [...d[c.steps+1][c.from],c.to] : d[c.steps+1][c.from]=[c.to]
  //{[arr[0].to]:[]}
  if (d.length===c.steps) {
    d.push({[`${c.from}`]:[{"id":`${c.to}`,"order":c.order}]})
    w[c.steps] = 1
  }
  else {
    if(d[c.steps][`${c.from}`]) { 
      d[c.steps][`${c.from}`] = [...d[c.steps][`${c.from}`],{"id":`${c.to}`,"order":c.order}]
      w[c.steps] += 1
    }
    else {
      d[c.steps][`${c.from}`]=[{"id":`${c.to}`,"order":c.order}]
      w[c.steps] += 1
    }
  }

  return {
    "nodes": d,
    "width": w,
    "n":n,
    "max": w[c.steps] > a.max.val ? {"pos":c.steps, "val": w[c.steps]} : a.max
  }
},{"nodes":[], "width": [], "max":{"pos":0, "val":0}, "n":{}})

const maxVal =  $.max.val

const width = 150
const height = 50
const row = 50
const tier = 120
const color = "#006FBA"
const connColor = "#717171"
const max = maxVal * width + (maxVal+1) *row



const data=[]
const connector=[]



const uNodes = [...$.nodes]
const uWidth = [...$.width]
const n = $.n
const dY = tier


Object.entries(n).forEach(([k,v],i,r) =>{
  Object.entries(v).forEach(([kk, vv],ii,rr) =>{  
    data.push({
        "id": vv,

        "label": vv,
        "color": color,
        "x":((maxVal)*(row)+ (maxVal*width))/(rr.length+1) + ((maxVal)*(row)+ (maxVal*width))/(rr.length+1)*(ii),
        "y": dY+height*r.length/2 - tier*(k+1),//dY+height*k/2 + tier*(k+1),
        "shape":"rectangle",
        "width":width,
        "height":height
    }) 
  })
})

for (let i=0; i<uNodes.length; i++) {
  for (const [k,v] of Object.entries(uNodes[i])) {
    connector.push(...v.map(e=>({  
      "from": k,
      "to": e.id,
      "label": e.qty,
      "color": connColor,
      "strength": "1",
      "arrowatstart": "0",
      "arrowatend": "1",
      "alpha": "100"
    })))
}
}

return ({
  "data": {
    "data":data,
    "connector":connector
  }
})

