data.query:
query Query($where: ProductStrategyProcessWhereInput, $orderBy: [ProductStrategyProcessOrderByInput!], $first: Int, $after: String) {
  productStrategyProcess(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        code
        order
        componentBoms {
          edges {
            node {
              id 
              componentProductStrategyProcessId
      }
    }
    }
        assemblyBoms {
          edges {
            node {
              id
              order
              maximumUsage
              minimumUsage
              productionOffalAllowed
              setupOffalAllowed
              standardPackQuantity
              standardUsage
              active
              actualUsage
              componentType
              consumeOnProduction
              defaultPackaging
              transferSerial
              useOnWorkOrder
              validateOnProduction
              externalId
              reference
              assemblyProductStrategyProcessId
              componentPackagingMaterialId
              componentProductId
              componentProductStrategyId
              componentProductStrategyProcessId
              toolTypeId
            }
          }
        }
      }
    }
  }
}

